public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Searches for public channel posts containing the given hashtag or cashtag. For optimal performance, the number of returned messages is chosen by TDLib and can be smaller than the specified limit
    /// </summary>
    public Task<TdLib.TdApi.Objects.FoundMessages> SearchPublicMessagesByTagAsync(string tag = default, string offset = default, int limit = default)
    {

           using var activity =  StartCallActivity("SearchPublicMessagesByTagAsync", typeof(SearchPublicMessagesByTag).FullName ?? "SearchPublicMessagesByTagAsync");

           try
           {
             return client.SearchPublicMessagesByTagAsync(tag, offset, limit);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
